          <Space direction="vertical" size={0}>
            <Typography.Text type="secondary">
              Punch: {formatDate(record.punch_date)}
            </Typography.Text>
            <Typography.Text type="secondary">
              Clear: {formatDate(record.clear_date)}
            </Typography.Text>
          </Space>
        ),
      },
      {
        title: 'Top Punch',
