{"output":"import {
  Alert,
  Breadcrumb,
  Card,
  Input,
  Progress,
  Select,
  Space,
  Statistic,
  Table,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, Navigate, useNavigate, useParams } from 'react-router-dom';
import { axiosInstance } from '../api/client';
import type { TagWithStats } from '../api/types';
import './SubsystemDetailPage.css';

const SubsystemDetailPage = () => {
  const { sys_code: sysCodeParam, subsys_code: subsysCodeParam } = useParams();
  const navigate = useNavigate();
  const [allTags, setAllTags] = useState<TagWithStats[]>([]);
  const [filteredTags, setFilteredTags] = useState<TagWithStats[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [openPunchFilter, setOpenPunchFilter] = useState<'all' | 'yes' | 'no'>('all');
  const [completionFilter, setCompletionFilter] = useState<'all' | 'full' | 'partial'>('all');

  const loadTags = useCallback(async () => {
    if (!sysCodeParam || !subsysCodeParam) return;
    try {
      setLoading(true);
      setError(null);
      const response = await axiosInstance.get<TagWithStats[]>(
        `/subsystems/${encodeURIComponent(sysCodeParam)}/${encodeURIComponent(subsysCodeParam)}/tags`,
      );
      setAllTags(response.data);
      setFilteredTags(response.data);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load tags';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [sysCodeParam, subsysCodeParam]);

  useEffect(() => {
    void loadTags();
  }, [loadTags]);

  if (!sysCodeParam || !subsysCodeParam) {
    return <Navigate to="/subsystems" replace />;
  }

  const sysCode = sysCodeParam;
  const subsysCode = subsysCodeParam;

  const filterTags = useCallback(
    (source: TagWithStats[]) => {
      const term = search.trim().toLowerCase();
      return source.filter((tag) => {
        const matchesSearch = !term
          ? true
          : [tag.tag_no, tag.description ?? '', tag.location ?? '', tag.discipline ?? '']
              .join(' ')
              .toLowerCase()
              .includes(term);

        const hasOpenPunch = tag.punch_open_count > 0;
        const matchesPunchFilter =
          openPunchFilter === 'all' ||
          (openPunchFilter === 'yes' && hasOpenPunch) ||
          (openPunchFilter === 'no' && !hasOpenPunch);

        const isComplete = tag.mcr_closed_count >= tag.mcr_count;
        const matchesCompletionFilter =
          completionFilter === 'all' ||
          (completionFilter === 'full' && isComplete) ||
          (completionFilter === 'partial' && tag.mcr_closed_count < tag.mcr_count);

        return matchesSearch && matchesPunchFilter && matchesCompletionFilter;
      });
    },
    [completionFilter, openPunchFilter, search],
  );

  const applyTagFilters = useCallback(
    (source?: TagWithStats[]) => {
      const base = source ?? allTags;
      setFilteredTags(filterTags(base));
    },
    [allTags, filterTags],
  );

  useEffect(() => {
    applyTagFilters();
  }, [applyTagFilters]);

  const summary = useMemo(() => {
    return allTags.reduce(
      (
        acc,
        { mcr_count, mcr_closed_count, punch_count, punch_open_count },
      ) => {
        acc.mcrTotal += mcr_count;
        acc.mcrClosed += mcr_closed_count;
        acc.punchTotal += punch_count;
        acc.punchOpen += punch_open_count;
        acc.tagTotal += 1;
        return acc;
      },
      { mcrTotal: 0, mcrClosed: 0, punchTotal: 0, punchOpen: 0, tagTotal: 0 },
    );
  }, [allTags]);

  const columns: ColumnsType<TagWithStats> = [
    {
      title: 'Tag',
      dataIndex: 'tag_no',
      sorter: (a, b) => a.tag_no.localeCompare(b.tag_no),
    },
    {
      title: 'Description',
      dataIndex: 'description',
      render: (value: string | null) => value ?? '-',
    },
    {
      title: 'Location',
      dataIndex: 'location',
      render: (value: string | null) => value ?? '-',
    },
    {
      title: 'MCR Count',
      dataIndex: 'mcr_count',
    },
    {
      title: 'MCR Closed',
      dataIndex: 'mcr_closed_count',
    },
    {
      title: 'Punch Count',
      dataIndex: 'punch_count',
    },
    {
      title: 'Punch Open',
      dataIndex: 'punch_open_count',
    },
    {
      title: 'Completion',
      key: 'completion',
      render: (_, record) => {
        const percent = record.mcr_count
          ? Math.round((record.mcr_closed_count / record.mcr_count) * 100)
          : 0;
        return <Progress percent={percent} size="small" status={percent === 100 ? 'success' : 'active'} />;
      },
    },
  ];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Breadcrumb
        items={[
          { title: <Link to="/subsystems">Subsystems</Link> },
          { title: `${sysCode} / ${subsysCode}` },
        ]}
      />

      <Typography.Title level={3} style={{ margin: 0 }}>
        Subsystem {sysCode}-{subsysCode}
      </Typography.Title>

      <Card>
        <Space size="large" wrap>
          <Statistic title="Tags" value={summary.tagTotal} />
          <Statistic
            title="MCR Closed"
            value={summary.mcrTotal ? ((summary.mcrClosed / summary.mcrTotal) * 100).toFixed(1) : '0.0'}
            suffix="%"
          />
          <Statistic title="Punch Open" value={summary.punchOpen} />
        </Space>
      </Card>

      <Card
        title="Tags"
        extra={
          <Input.Search
            placeholder="Search tag, description, location"
            allowClear
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            style={{ width: 260 }}
          />
        }
      >
        {error && (
          <Alert
            type="error"
            message="Failed to load tags"
            description={error}
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}
        <Space wrap size="middle" style={{ marginBottom: 16 }}>
          <Select
            value={openPunchFilter}
            onChange={(value) => setOpenPunchFilter(value)}
            style={{ width: 180 }}
            options={[
              { label: 'Has Open Punch: All', value: 'all' },
              { label: 'Has Open Punch: Yes', value: 'yes' },
              { label: 'Has Open Punch: No', value: 'no' },
            ]}
          />
          <Select
            value={completionFilter}
            onChange={(value) => setCompletionFilter(value)}
            style={{ width: 180 }}
            options={[
              { label: 'Completion: All', value: 'all' },
              { label: 'Completion: 100%', value: 'full' },
              { label: 'Completion: <100%', value: 'partial' },
            ]}
          />
        </Space>
        <Table<TagWithStats>
          rowKey={(record) => `${record.id}`}
          columns={columns}
          dataSource={filteredTags}
          loading={loading}
          pagination={{ pageSize: 20 }}
          onRow={(record) => ({
            onClick: () =>
              navigate(
                `/tags/${encodeURIComponent(record.sys_code)}/${encodeURIComponent(record.subsys_code)}/${encodeURIComponent(record.tag_no)}`,
              ),
","metadata":{"exit_code":0,"duration_seconds":4.2}}

{"output":"              ),
            style: { cursor: 'pointer' },
          })}
          rowClassName={(record) => {
            if (record.punch_open_count > 0) {
              return 'tag-row-punch-open';
            }
            if (record.mcr_closed_count < record.mcr_count) {
              return 'tag-row-incomplete';
            }
            return '';
          }}
        />
      </Card>
    </Space>
  );
};

export default SubsystemDetailPage;
