import type { ColumnsType } from 'antd/es/table';
import { useEffect, useMemo, useState } from 'react';
import { Link, Navigate, useNavigate, useParams } from 'react-router-dom';
import { axiosInstance } from '../api/client';
import type { MCItem, Punch, TagDetail } from '../api/types';
import './TagDetailPage.css';

const formatDate = (value: string | null) => {
  if (!value) return '-';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return new Intl.DateTimeFormat('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }).format(date);
};

const getMCStatusColor = (status: string) => {
  if (status === 'Complete') return 'green';
  if (status === 'UnCheck') return 'default';
  return 'orange';
};

const getPunchClassColor = (abClass: string | null) => {
  if (abClass === 'A') return 'red';
  if (abClass === 'B') return 'blue';
  return 'default';
};

const TagDetailPage = () => {
  const { sys_code: sysCodeParam, subsys_code: subsysCodeParam, tag_no: tagNoParam } = useParams();
  const navigate = useNavigate();
  const [tagDetail, setTagDetail] = useState<TagDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchTag = async () => {
      if (!sysCodeParam || !subsysCodeParam || !tagNoParam) return;
      try {
        setLoading(true);
        setError(null);
        const response = await axiosInstance.get<TagDetail>(
          `/tags/${encodeURIComponent(sysCodeParam)}/${encodeURIComponent(subsysCodeParam)}/${encodeURIComponent(tagNoParam)}/details`,
        );
        setTagDetail(response.data);
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Failed to load tag';
        setError(message);
      } finally {
        setLoading(false);
      }
    };

    void fetchTag();
  }, [sysCodeParam, subsysCodeParam, tagNoParam]);

  if (!sysCodeParam || !subsysCodeParam || !tagNoParam) {
    return <Navigate to="/subsystems" replace />;
  }

  const sysCode = sysCodeParam;
  const subsysCode = subsysCodeParam;
  const tagNo = tagNoParam;

  const breadcrumbRoutes = [
    { path: '/subsystems', breadcrumbName: 'Subsystems' },
    {
      path: `/subsystems/${encodeURIComponent(sysCode)}/${encodeURIComponent(subsysCode)}`,
      breadcrumbName: `${sysCode} / ${subsysCode}`,
    },
    { path: '#', breadcrumbName: `Tag ${tagNo}` },
  ];

  const mcItems = tagDetail?.mcitems ?? [];
  const punches = tagDetail?.punches ?? [];

  const mcClosedCount = useMemo(() => mcItems.filter((item) => item.status === 'Complete').length, [mcItems]);
  const punchOpenCount = useMemo(() => punches.filter((punch) => !punch.clear_date).length, [punches]);

  const mcColumns: ColumnsType<MCItem> = useMemo(
    () => [
      {
