      },
      {
        title: 'Clear Date',
        dataIndex: 'clear_date',
        render: (value: string | null) => formatDate(value),
      },
      {
        title: 'Responsible',
        dataIndex: 'responsible',
        render: (value: string | null) => value ?? '-',
      },
      {
        title: 'Department',
        dataIndex: 'dept',
        render: (value: string | null) => value ?? '-',
      },
      {
        title: 'TOP',
        dataIndex: 'is_top',
        render: (value: string | null) => (value === 'Y' ? <Tag color="gold">TOP</Tag> : '-'),
      },
    ],
    [],
  );

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <PageHeader
        className="tag-detail-page-header"
        onBack={() => navigate(-1)}
        title={`${sysCode}.${subsysCode} - ${tagNo}`}
        breadcrumb={{
          routes: breadcrumbRoutes,
          itemRender: (route, _, routes) => {
            const isLast = routes.indexOf(route) === routes.length - 1;
            return isLast ? route.breadcrumbName : <Link to={route.path}>{route.breadcrumbName}</Link>;
          },
        }}
      />

      {error && (
        <Alert
          type="error"
          message="Unable to load tag details"
          description={error}
          showIcon
        />
      )}

      <Card loading={loading}>
        <Row gutter={[24, 24]}>
          <Col xs={24} lg={14}>
            <Descriptions column={2} bordered size="small">
              <Descriptions.Item label="Tag No">{tagDetail?.tag?.tag_no ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="System">{tagDetail?.tag?.sys_code ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="Subsystem">{tagDetail?.tag?.subsys_code ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="Discipline">{tagDetail?.tag?.discipline ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="Location">{tagDetail?.tag?.location ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="Scope">{tagDetail?.tag?.scope ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="Description" span={2}>
                {tagDetail?.tag?.description ?? '-'}
              </Descriptions.Item>
              <Descriptions.Item label="Reference Drawing" span={2}>
                {tagDetail?.tag?.ref_drawing ?? '-'}
              </Descriptions.Item>
            </Descriptions>
          </Col>
          <Col xs={24} lg={10}>
            <Space direction="vertical" size="large" style={{ width: '100%' }}>
              <Card size="small">
                <Statistic title="MC Items" value={mcClosedCount} suffix={` / ${mcItems.length}`} />
              </Card>
              <Card size="small">
                <Statistic title="Punches" value={punchOpenCount} suffix={` / ${punches.length}`} />
              </Card>
            </Space>
          </Col>
        </Row>
      </Card>

      <Card title={`MC Items (${mcItems.length})`} loading={loading}>
        <Table<MCItem>
          rowKey={(record) => `${record.id}`}
          columns={mcColumns}
          dataSource={mcItems}
          pagination={false}
          rowClassName={(record) => (record.status === 'Complete' ? '' : 'mc-row-pending')}
        />
      </Card>

      <Card title={`Punches (${punches.length})`} loading={loading}>
        <Table<Punch>
          rowKey={(record) => `${record.id}`}
          columns={punchColumns}
          dataSource={punches}
          pagination={false}
          rowClassName={(record) => {
